def _build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head

def _to_list(node):
    out = []
    while node is not None and len(out) < 10000:
        out.append(node.val)
        node = node.next
    return out

def test_basic():
    assert _to_list(reverse_list(_build([1, 2, 3]))) == [3, 2, 1]

def test_two_nodes():
    assert _to_list(reverse_list(_build([7, 8]))) == [8, 7]

def test_single_and_empty():
    assert _to_list(reverse_list(_build([5]))) == [5]
    assert reverse_list(None) is None

def test_in_place():
    head = _build([1, 2, 3, 4])
    tail = head.next.next.next
    new_head = reverse_list(head)
    assert new_head is tail
    assert head.next is None
